class Vehicle:
    def __init__(self, brand):
        self.brand = brand

    def describe(self):
        return f'{self.brand} vehicle'

class Car(Vehicle):
    def __init__(self, brand, doors):
        super().__init__(brand)
        self.doors = doors

    def describe(self):
        base = super().describe()
        return f'{base} with {self.doors} doors'

c = Car('Toyota', 4)
print(c.describe())
print(isinstance(c, Vehicle))
